<?php
declare(strict_types=1);
if (!defined('ABSPATH')) exit;
$postId = (int) ($GLOBALS['es_project_id'] ?? get_the_ID());
if ($postId < 1) return;
$imageKeys = ['second-image', 'three-image', 'foure-image', 'five-image', 'six-image'];
$imageIds = [];
$featuredId = (int) get_post_thumbnail_id($postId);
if ($featuredId > 0) $imageIds[] = $featuredId;
foreach ($imageKeys as $key) { $attachmentId = (int) get_post_meta($postId, $key, true); if ($attachmentId > 0) $imageIds[] = $attachmentId; }
$imageIds = array_values(array_unique($imageIds));
$slides = [];
foreach ($imageIds as $attachmentId) { $src = wp_get_attachment_image_url($attachmentId, 'large'); $thumb = wp_get_attachment_image_url($attachmentId, 'thumbnail'); $slides[] = ['id' => $attachmentId, 'src' => is_string($src) && $src !== '' ? $src : es_image_uri('factory.jpg'), 'thumb' => is_string($thumb) && $thumb !== '' ? $thumb : es_image_uri('factory.jpg')]; }
if ($slides === []) $slides[] = ['id' => 0, 'src' => es_image_uri('factory.jpg'), 'thumb' => es_image_uri('factory.jpg')];
$types = get_the_terms($postId, 'project_type'); $cities = get_the_terms($postId, 'city'); $finish = trim((string) get_post_meta($postId, 'finish-pro-time', true));
$contactUrl = add_query_arg(['project' => $postId], home_url('/contact/'));
?>
<section class="grid gap-6 lg:grid-cols-[minmax(0,1.35fr)_minmax(280px,.65fr)]" aria-label="گالری و اطلاعات پروژه">
    <div class="space-y-3" data-gallery-root="true"><div class="relative overflow-hidden rounded-3xl bg-white"><img data-gallery-main-img="true" src="<?php echo esc_url($slides[0]['src']); ?>" alt="تصویر پروژه <?php echo esc_attr(get_the_title($postId)); ?>" class="aspect-[16/10] w-full object-cover" loading="eager" fetchpriority="high" decoding="async"><span data-gallery-counter="true" class="absolute bottom-4 left-4 rounded-full bg-slate-900/75 px-3 py-1 text-xs font-bold text-white">۱ / <?php echo esc_html((string) count($slides)); ?></span><button type="button" data-gallery-prev="true" aria-label="تصویر قبلی" class="absolute right-3 top-1/2 grid h-10 w-10 -translate-y-1/2 place-items-center rounded-full bg-white">‹</button><button type="button" data-gallery-next="true" aria-label="تصویر بعدی" class="absolute left-3 top-1/2 grid h-10 w-10 -translate-y-1/2 place-items-center rounded-full bg-white">›</button><button type="button" data-gallery-expand="true" aria-label="نمایش تصویر بزرگ" class="absolute left-4 top-4 grid h-10 w-10 place-items-center rounded-full bg-white">⤢</button></div>
        <div class="flex gap-2 overflow-x-auto"><?php foreach ($slides as $index => $slide) : ?><button type="button" data-gallery-thumb="<?php echo esc_attr((string) $index); ?>" data-gallery-attachment="<?php echo esc_attr((string) $slide['id']); ?>" data-gallery-src="<?php echo esc_url($slide['src']); ?>" class="shrink-0 rounded-xl border border-slate-200 p-1"><img src="<?php echo esc_url($slide['thumb']); ?>" alt="تصویر پروژه <?php echo esc_attr((string) ($index + 1)); ?>" class="h-16 w-20 rounded-lg object-cover" loading="lazy" decoding="async"><span data-gallery-thumb-ring class="hidden"></span></button><?php endforeach; ?></div>
        <div data-gallery-lightbox="true" class="fixed inset-0 z-[110] hidden items-center justify-center bg-slate-950/95 p-4" role="dialog" aria-modal="true" aria-label="گالری پروژه"><button type="button" data-gallery-lightbox-close="true" aria-label="بستن" class="absolute right-5 top-5 grid h-11 w-11 place-items-center rounded-full bg-white text-2xl">×</button><button type="button" data-gallery-lightbox-prev="true" aria-label="تصویر قبلی" class="absolute right-4 top-1/2 rounded-full bg-white p-3">‹</button><img data-gallery-lightbox-img="true" src="<?php echo esc_url($slides[0]['src']); ?>" alt="تصویر پروژه" class="max-h-[85vh] max-w-[90vw] object-contain"><button type="button" data-gallery-lightbox-next="true" aria-label="تصویر بعدی" class="absolute left-4 top-1/2 rounded-full bg-white p-3">›</button><div class="absolute bottom-5 flex gap-2"><?php foreach ($slides as $index => $_slide) : ?><button type="button" data-gallery-lightbox-dot="<?php echo esc_attr((string) $index); ?>" class="h-2 w-2 rounded-full bg-white/40" aria-label="تصویر <?php echo esc_attr((string) ($index + 1)); ?>"></button><?php endforeach; ?></div></div>
    </div>
    <aside class="h-fit rounded-3xl border border-slate-200 bg-white p-5 md:p-7" data-project-info><h2 class="mb-4 text-lg font-black text-slate-900">شناسنامه پروژه</h2><dl class="space-y-3 text-sm"><?php if ($finish !== '') : ?><div class="flex justify-between gap-3 border-b border-slate-100 pb-3"><dt class="text-slate-500">زمان تکمیل</dt><dd class="font-bold"><?php echo esc_html($finish); ?></dd></div><?php endif; ?><?php if (is_array($cities)) foreach ($cities as $term) : ?><div class="flex justify-between gap-3 border-b border-slate-100 pb-3"><dt class="text-slate-500">محل اجرا</dt><dd class="font-bold"><?php echo esc_html($term->name); ?></dd></div><?php endforeach; ?><?php if (is_array($types)) foreach ($types as $term) : ?><div class="flex justify-between gap-3 border-b border-slate-100 pb-3"><dt class="text-slate-500">نوع پروژه</dt><dd class="font-bold"><?php echo esc_html($term->name); ?></dd></div><?php endforeach; ?></dl><a href="<?php echo esc_url($contactUrl); ?>" class="mt-5 block rounded-xl bg-emerald-700 px-4 py-3 text-center text-sm font-extrabold text-white">مشاوره پروژه مشابه</a></aside>
</section>
